// RetailLens plan v2, with SYNTHETIC data only: the pasted stock report (read, edit, copy back out), the report checked against scanned phones,
// the person's own segments, and the target levels (70-120). No real report, name or number is used here.
import assert from 'node:assert/strict';
import { readFile, writeFile, mkdtemp, mkdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { pathToFileURL } from 'node:url';
import ts from 'typescript';

const dir = await mkdtemp(join(tmpdir(), 'imei-retail2-'));
const files = ['whatsapp-ready', 'routine-keeper', 'assistant-settings', 'retail/assistant-tasks', 'retail/routine-schedule', 'retail/capabilities', 'retail/routines', 'retail/attention', 'processing-options', 'home-options', 'retail/people-commands', 'retail/calendar-commands', 'retail/assistant-actions', 'people', 'phone-names', 'samsung-models', 'retail/types', 'retail/planning', 'retail/dated-reports', 'retail/autogive', 'retail/allocation', 'retail/catalog', 'retail/data', 'retail/planning-data', 'retail/availability', 'retail/shift-codes', 'retail/availability-import', 'retail/daily-uploads', 'retail/delivery', 'retail/auto-workflow', 'retail/local-assistant', 'retail/accessory-report', 'imei-validate', 'retail/store-targets', 'retail/sales', 'retail/inventory', 'retail/targets', 'retail/pace', 'retail/stockreport', 'retail/colours', 'retail/reconcile', 'retail/segments', 'retail/reportsync', 'retail/soldsync', 'retail/targetsummary', 'retail/dashboard', 'retail/forecast', 'retail/colour-dictionary', 'retail/colourlist'];
for (const name of files) {
  const source = (await readFile(`src/${name}.ts`, 'utf8')).replace(/from '(\.{1,2}\/[^']+)'/g, (_, path) => `from '${path}.mjs'`);
  await mkdir(dirname(join(dir, name)), { recursive: true });
  await writeFile(join(dir, `${name}.mjs`), ts.transpileModule(source, { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ES2022 } }).outputText);
}
const load = name => import(pathToFileURL(join(dir, `${name}.mjs`)).href);
const T = await load('retail/types'), C = await load('retail/catalog'), D = await load('retail/data'), G = await load('retail/targets'),
  P = await load('retail/stockreport'), PC = await load('retail/pace'), FC = await load('retail/forecast'), X = await load('retail/reconcile'), SG = await load('retail/segments');


const PL=await load('retail/planning'), SS=await load('retail/soldsync'), RS=await load('retail/reportsync'), I=await load('retail/inventory');
const today='2026-11-18', month='2026-11';
const testImei = i => { const b='49015420'+String(i).padStart(6,'0');let sum=0;for(let j=0;j<b.length;j++){let n=+b[b.length-1-j];if(j%2===0){n*=2;if(n>9)n-=9;}sum+=n;}return b+String((10-sum%10)%10); };
const records=Array.from({length:120},(_,i)=>({id:'demo'+i,imei:testImei(i),model:'SM-S948B',personId:'me',raw:'12GB | 256GB',name:'Demo',createdAt:new Date(2026,10,1,0,i).toISOString()}));
const base=()=>{let s={...D.emptyState(),soldLedger:{},recordMeta:Object.fromEntries(records.map(r=>[r.id,{status:'held',segment:'flagship1'}])),targets:{[month]:{me:{personId:'me',month,source:'manual',importedAt:'2026-11-01T00:00:00Z',lines:[{segment:'flagship1',target:100,achieved:40,cap:100}]}}}};s.report=RS.withBaseline(s,P.parseReport('S26 Ultra 256GB : 00/120'),records);return s;};
const request={personId:'me',segments:['flagship1'],method:'goal',value:70,date:today,until:'2026-11-30',reserve:0,skipDays:[],priority:'lowest',milestones:[{date:today,percent:70}]};
const ach=s=>s.targets[month].me.lines[0].achieved;
let count=0;const check=(name,fn)=>{fn();console.log('PASS:',name);count++;};
check('approval reserves 30 actual phones without recording sales',()=>{const s=base(),d=PL.draftPlan(s,records,request),n=PL.approvePlan(s,records,d);assert.equal(d.entries[0].recordIds.length,30);assert.equal(ach(n),40);assert.equal(I.realStock(n,records).length,120);assert.equal(n.releases?.length||0,0);});
let approved=PL.approvePlan(base(),records,PL.draftPlan(base(),records,request));
const p=approved.releasePlans[0],e=p.entries[0];
let released=PL.confirmRelease(approved,records,p.id,e.id,today);
check('confirmed release counts toward targets once, leaves reporting pending, reduces real stock',()=>{assert.equal(ach(released),70);assert.equal(I.realStock(released,records).length,90);assert.equal(PL.pendingReleases(released).length,30);assert.equal(P.listedSold(released.report),0);assert.throws(()=>PL.confirmRelease(released,records,p.id,e.id,today));assert.equal(SS.syncSold(released,records,today).state,released);});
released={...released,report:RS.syncScans(released,released.report,records).report};
let partial=PL.includeReleased(released,released.releases[0].recordIds.slice(0,20));
check('20 reported, 10 pending, achievement70 and stock90 unchanged',()=>{assert.equal(P.listedSold(partial.report),20);assert.equal(PL.pendingReleases(partial).length,10);assert.equal(ach(partial),70);assert.equal(I.realStock(partial,records).length,90);assert.equal(P.reportItems(partial.report)[0].stock,90);});
check('repeated report selection cannot count twice',()=>{const repeat=PL.includeReleased(partial,partial.releases[0].recordIds.slice(0,20));assert.equal(P.listedSold(repeat.report),20);assert.equal(PL.pendingReleases(repeat).length,10);});
check('undo restores stock and target and reverses only reported quantities',()=>{const n=PL.undoRelease(partial,records,partial.releases[0].id,today);assert.equal(ach(n),40);assert.equal(I.realStock(n,records).length,120);assert.equal(P.listedSold(n.report),0);assert.equal(PL.pendingReleases(n).length,0);assert.equal(n.releases[0].status,'undone');});
check('future releases cannot happen early',()=>{const req={...request,date:'2026-11-20'},s=PL.approvePlan(base(),records,PL.draftPlan(base(),records,req));assert.throws(()=>PL.confirmRelease(s,records,s.releasePlans[0].id,s.releasePlans[0].entries[0].id,today));});
check('external stock changes require review',()=>{const changed={...approved,recordMeta:{...approved.recordMeta,demo0:{status:'sold',segment:'flagship1'}}};assert.throws(()=>PL.confirmRelease(changed,records,p.id,e.id,today),/changed/);});
check('spread keeps exact totals with whole daily units and daily limits',()=>{const req={...request,method:'spread',until:'2026-11-24',dailyLimit:5},d=PL.draftPlan(base(),records,req);assert.equal(d.entries.reduce((s,e)=>s+e.recordIds.length,0),30);assert.ok(d.entries.every(e=>e.recordIds.length<=5));assert.equal(new Set(d.entries.flatMap(e=>e.recordIds)).size,30);});
check('milestones are cumulative and remaining plan stays valid after its own release',()=>{const req={...request,method:'milestones',milestones:[{date:today,percent:70},{date:'2026-11-20',percent:90}]},s=PL.approvePlan(base(),records,PL.draftPlan(base(),records,req)),p=s.releasePlans[0];assert.deepEqual(p.entries.map(e=>e.recordIds.length),[30,20]);const one=PL.confirmRelease(s,records,p.id,p.entries[0].id,today);const two=PL.confirmRelease(one,records,p.id,p.entries[1].id,'2026-11-20');assert.equal(ach(two),90);});
check('reserve and insufficient stored stock are visible as shortage',()=>{const d=PL.draftPlan(base(),records.slice(0,15),{...request,reserve:5});assert.equal(d.entries[0].recordIds.length,10);assert.equal(d.entries[0].required,30);});
check('caps and typed milestone quantities are respected',()=>{const s=base();s.targets[month].me.lines[0]={segment:'flagship1',target:100,achieved:40,cap:70,levels:{70:65}};const d=PL.draftPlan(s,records,{...request,value:120});assert.equal(d.entries[0].recordIds.length,25);});
check('pending upload, duplicate, review and other owners are ineligible',()=>{const s=base();s.pendingUploadIds=['demo0'];const bad=records.map((r,i)=>i===1?{...r,duplicate:true}:i===2?{...r,needsReview:true}:i===3?{...r,personId:'someone-else'}:r);const d=PL.draftPlan(s,bad,request);assert.ok(!d.entries.flatMap(e=>e.recordIds).some(id=>['demo0','demo1','demo2','demo3'].includes(id)));});
check('skipped dates and cross-month schedules cannot release',()=>{assert.equal(PL.draftPlan(base(),records,{...request,skipDays:[0,1,2,3,4,5,6]}).entries.reduce((n,e)=>n+e.recordIds.length,0),0);assert.equal(PL.draftPlan(base(),records,{...request,until:'2026-12-03'}).entries.length,0);});
check('percentage points, stored percentage and fixed quantities calculate correctly',()=>{for(const [method,value,want] of [['points',10,10],['stored',25,30],['quantity',8,8]]){const d=PL.draftPlan(base(),records,{...request,method,value});assert.equal(d.entries.reduce((n,e)=>n+e.recordIds.length,0),want);}});
check('backup cleaning preserves plan, release and partial reporting links',()=>{const n=D.cleanState(JSON.parse(JSON.stringify(partial)));assert.equal(n.releasePlans[0].id,p.id);assert.equal(n.releases[0].reportedIds.length,20);assert.equal(PL.pendingReleases(n).length,10);assert.equal(ach(n),70);assert.equal(D.cleanState({version:1}).releasePlans.length,0);});
check('report inclusion needs a report and live release',()=>{assert.throws(()=>PL.includeReleased({...released,report:undefined},released.releases[0].recordIds));assert.equal(PL.includeReleased(partial,['unknown']).releases[0].reportedIds.length,20);});
check('undo of an older release never subtracts new-day sellout',()=>{const nextDay={...partial,report:P.startNewDay(partial.report)};nextDay.report.entries=nextDay.report.entries.map(e=>e.t==='item'?{...e,sold:5}:e);const n=PL.undoRelease(nextDay,records,partial.releases[0].id,today);assert.equal(P.listedSold(n.report),5);});
check('already included option links IMEIs without adding pasted sold quantities',()=>{const n=PL.includeReleased(partial,partial.releases[0].recordIds.slice(20),true);assert.equal(P.listedSold(n.report),20);assert.equal(PL.pendingReleases(n).length,0);});
check('automatic daily refresh recalculates proposals without recording sales',()=>{const req={...request,method:'spread',until:'2026-11-20'},s=PL.approvePlan(base(),records,PL.draftPlan(base(),records,req));const next=PL.refreshCalculatedPlans(s,records,'2026-11-19');assert.equal(next.releasePlans[0].calculatedFor,'2026-11-19');assert.deepEqual(next.releasePlans[0].entries.map(e=>e.recordIds.length),[15,15]);assert.equal(ach(next),40);assert.equal(next.releases?.length||0,0);assert.equal(PL.refreshCalculatedPlans(next,records,'2026-11-19'),next);});
check('Not today redistributes within the end date and never records a sale',()=>{const req={...request,method:'spread',until:'2026-11-20'},s=PL.approvePlan(base(),records,PL.draftPlan(base(),records,req));const next=PL.skipReleaseToday(s,records,s.releasePlans[0].id,today);assert.deepEqual(next.releasePlans[0].entries.map(e=>[e.date,e.recordIds.length]),[['2026-11-19',15],['2026-11-20',15]]);assert.equal(ach(next),40);});
check('manual quantities stay fixed across daily refresh and remain capped',()=>{const req={...request,method:'spread',until:'2026-11-20',quantityMode:'manual',manualDaily:{'2026-11-18':{flagship1:5},'2026-11-19':{flagship1:15},'2026-11-20':{flagship1:10}}},s=PL.approvePlan(base(),records,PL.draftPlan(base(),records,req));assert.deepEqual(s.releasePlans[0].entries.map(e=>e.recordIds.length),[5,15,10]);assert.equal(PL.refreshCalculatedPlans(s,records,'2026-11-19'),s);});
const DR=await load('retail/dated-reports');
check('dated automatic reports compare with actual stock and edits cannot change it',()=>{const report=DR.calculatedDatedReport(partial,records,today,today);assert.equal(DR.compareDatedReport(partial,records,report,today,today).match,true);const changed={...report,entries:report.entries.map(e=>e.t==='item'?{...e,stock:e.stock+7}:e)};const comparison=DR.compareDatedReport(partial,records,changed,today,today);assert.equal(comparison.match,false);assert.equal(comparison.realStock,90);assert.equal(I.realStock(partial,records).length,90);assert.equal(ach(partial),70);});
check('future reports are explicit projections, preserve true stock and survive backup',()=>{const req={...request,date:'2026-11-20'},s=PL.approvePlan(base(),records,PL.draftPlan(base(),records,req));const report=DR.calculatedDatedReport(s,records,'2026-11-20',today),comparison=DR.compareDatedReport(s,records,report,'2026-11-20',today);assert.equal(comparison.future,true);assert.equal(comparison.match,true);assert.equal(comparison.realStock,120);assert.equal(comparison.expectedStock,90);assert.match(DR.datedReportText(report,'2026-11-20',today),/PROJECTED DRAFT/);const restored=D.cleanState({...s,reportDrafts:{'2026-11-20':{report,mode:'manual',updatedAt:'now'}}});assert.equal(restored.reportDrafts['2026-11-20'].mode,'manual');});
const AV=await load('retail/availability'), AU=await load('retail/autogive');
check('regular days off, specific off dates and annual leave block automatic suggestions',()=>{const s=base();s.workSchedules={me:{offWeekdays:[3],offDates:[],annualLeave:[]}};assert.equal(AV.availability(s,'me',today),'off');let rec=AU.recommendFor(s,month,today,[{id:'me',name:'Demo'}],records.map(r=>({...r,personId:''})));assert.equal(rec.proposals.length,0);s.workSchedules.me={offWeekdays:[],offDates:[today],annualLeave:[]};assert.equal(AV.isWorking(s,'me',today),false);s.workSchedules.me={offWeekdays:[],offDates:[],annualLeave:[{id:'leave',start:today,end:'2026-11-24'}]};assert.equal(AV.availability(s,'me',today),'annual leave');assert.equal(AV.isWorking(s,'me','2026-11-25'),true);});
check('daily release calculations skip off days and use editable calculation days',()=>{const s=base();s.workSchedules={me:{offWeekdays:[],offDates:[today],annualLeave:[],offDivisor:{[month]:2}}};const d=PL.draftPlan(s,records,{...request,method:'spread',until:'2026-11-21'});assert.deepEqual(d.entries.map(e=>[e.date,e.recordIds.length]),[['2026-11-19',15],['2026-11-20',15]]);});
check('net coverage helper totals16 as8 each without mutating target state',()=>{const s=base();s.workSchedules={me:{offWeekdays:[],offDates:[],annualLeave:[{id:'leave',start:today,end:'2026-11-24'}]}};s.leaveTransfers=[{id:'coverage',personId:'me',start:today,end:'2026-11-24',createdAt:'now',status:'active',segments:[{segment:'flagship1',total:16,shares:[{personId:'b',units:8},{personId:'c',units:8}]}]}];assert.equal(AV.coverageUnits(s,'me','flagship1','2026-11-01','2026-11-30'),-16);assert.equal(AV.coverageUnits(s,'b','flagship1','2026-11-01','2026-11-30'),8);assert.equal(AV.coverageUnits(s,'c','flagship1','2026-11-01','2026-11-30'),8);assert.equal(ach(s),40);assert.equal(s.targets[month].me.lines[0].target,100);s.workSchedules.b={offWeekdays:[],offDates:[],annualLeave:[{id:'off',start:today,end:'2026-11-24'}]};assert.equal(AV.coverageUnits(s,'b','flagship1','2026-11-01','2026-11-30'),0);assert.equal(AV.coverageUnits(s,'me','flagship1','2026-11-01','2026-11-30'),-8,'unplaceable coverage is not deducted');});
check('editable annual-leave divisor changes estimated transfer and persists',()=>{const s=base();s.workSchedules={me:{offWeekdays:[],offDates:[],annualLeave:[],calculationDays:{[month]:26},leaveDivisor:{[month]:30},offDivisor:{[month]:10}}};const a=AV.suggestedLeaveTransfer(s,'me',today,'2026-11-24',['b','c'],today);assert.equal(a.segments[0].total,24);s.workSchedules.me.leaveDivisor[month]=15;const b=AV.suggestedLeaveTransfer(s,'me',today,'2026-11-24',['b','c'],today);assert.equal(b.segments[0].total,47);const saved=D.cleanState(s);assert.equal(saved.workSchedules.me.leaveDivisor[month],15);assert.equal(saved.workSchedules.me.offDivisor[month],10);assert.equal(saved.workSchedules.me.calculationDays[month],26);});
check('exact agreed AL calculation:40/(30-5)*5=8, adjusted32/44/44, store120',()=>{let s=D.emptyState();s.targets={[month]:Object.fromEntries(['a','b','c'].map(id=>[id,{personId:id,month,source:'manual',importedAt:'now',lines:[{segment:'flagship1',target:40,achieved:0,levels:{70:28}}]}]))};const transfer=AV.suggestedLeaveTransfer(s,'a',today,'2026-11-22',['b','c'],today);assert.equal(transfer.monthDays,30);assert.equal(transfer.leaveDays,5);assert.equal(transfer.divisor,25);assert.equal(transfer.segments[0].total,8);assert.deepEqual(transfer.segments[0].shares.map(p=>p.units),[4,4]);const applied=AV.applyLeaveTransfer(s,transfer);assert.deepEqual(['a','b','c'].map(id=>applied.targets[month][id].lines[0].target),[32,44,44]);assert.equal(Object.values(applied.targets[month]).reduce((n,p)=>n+p.lines[0].target,0),120);const edited=AV.applyLeaveTransfer(applied,{...applied.leaveTransfers[0],segments:[{segment:'flagship1',total:10,shares:[{personId:'b',units:5},{personId:'c',units:5}]}]});assert.deepEqual(['a','b','c'].map(id=>edited.targets[month][id].lines[0].target),[30,45,45]);const undone=AV.applyLeaveTransfer(edited,{...edited.leaveTransfers[0],status:'cancelled'});assert.deepEqual(['a','b','c'].map(id=>undone.targets[month][id].lines[0].target),[40,40,40]);assert.equal(undone.targets[month].a.lines[0].levels[70],28,'typed milestone restored exactly');});
const ST=await load('retail/store-targets');
check('store auto-division and existing AL adjustments remain balanced and editable',()=>{let s=ST.applyStoreTarget(D.emptyState(),month,'flagship1',120,ST.splitStoreTarget(120,['a','b','c']));assert.deepEqual(['a','b','c'].map(id=>s.targets[month][id].lines[0].target),[40,40,40]);s=AV.applyLeaveTransfer(s,AV.suggestedLeaveTransfer(s,'a',today,'2026-11-22',['b','c'],today));s=ST.applyStoreTarget(s,month,'flagship1',120,ST.splitStoreTarget(120,['a','b','c']));assert.deepEqual(['a','b','c'].map(id=>s.targets[month][id].lines[0].target),[32,44,44]);assert.equal(ST.promoterTotal(s,month,'flagship1'),120);assert.equal(s.storeTargets[month].flagship1,120);assert.throws(()=>ST.applyStoreTarget(s,month,'flagship1',120,[{personId:'a',units:100}]));const restored=D.cleanState(s);assert.equal(restored.storeTargets[month].flagship1,120);assert.equal(restored.leaveTransfers[0].adjustmentsApplied,true);});
check('saved availability calendar is rechecked before release, explicit override writes History',()=>{const s=base();s.workSchedules={me:{offWeekdays:[],offDates:[today],annualLeave:[]}};const req={...request,date:'2026-11-17',quantityMode:'manual',manualDaily:{'2026-11-17':{flagship1:30}}};const approved=PL.approvePlan(s,records,PL.draftPlan(s,records,req)),p=approved.releasePlans[0];assert.throws(()=>PL.confirmRelease(approved,records,p.id,p.entries[0].id,today),/calendar/);const next=PL.confirmRelease(approved,records,p.id,p.entries[0].id,today,true);assert.equal(ach(next),70);assert.ok(next.audit.some(a=>a.what==='off-day override'));});
check('manual-only availability calculations never alter targets or planning credit',()=>{let s=ST.applyStoreTarget(D.emptyState(),month,'flagship1',120,ST.splitStoreTarget(120,['a','b','c']));const transfer={...AV.suggestedLeaveTransfer(s,'a',today,'2026-11-22',['b','c'],today),status:'draft'};const manual=AV.applyLeaveTransfer(s,transfer);assert.deepEqual(['a','b','c'].map(id=>manual.targets[month][id].lines[0].target),[40,40,40]);assert.equal(AV.coverageUnits(manual,'b','flagship1','2026-11-01','2026-11-30'),0);const linked=AV.applyLeaveTransfer(manual,{...manual.leaveTransfers[0],status:'active'});assert.deepEqual(['a','b','c'].map(id=>linked.targets[month][id].lines[0].target),[32,44,44]);const unlinked=AV.applyLeaveTransfer(linked,{...linked.leaveTransfers[0],status:'draft'});assert.deepEqual(['a','b','c'].map(id=>unlinked.targets[month][id].lines[0].target),[40,40,40]);const restored=D.cleanState(unlinked);assert.equal(restored.leaveTransfers[0].status,'draft');});
check('calendar validation rejects impossible dates while accepting leap days',()=>{assert.equal(T.isDateKey('2026-02-31'),false);assert.equal(T.isDateKey('2028-02-29'),true);assert.equal(T.isDateKey('2026-02-29'),false);});
const RI=await load('retail/availability-import'), SH=await load('retail/shift-codes'), DU=await load('retail/daily-uploads');
check('roster interpretation handles dated rows and code matrices without phone records',()=>{const s=base(),people=[{id:'me',name:'Demo A'}];const result=RI.parseRosterGrid(RI.csvGrid('Person,Date,Code\nDemo A,18/11/2026,MX1\nDemo A,19/11/2026,AL'),s,people,month,'DMY','demo.csv');assert.equal(result.entries.length,2);assert.equal(result.entries[0].start,today);assert.equal(result.entries[0].code,'MX1');assert.equal(result.entries[1].available,false);assert.deepEqual(result.entries.flatMap(e=>RI.rosterIssues(e,s)),[]);const applied=RI.applyRoster(s,result.entries,'manual',true);assert.equal(applied.workSchedules.me.windows.length,2);assert.equal(applied.sales.length,0);assert.equal(I.realStock(applied,records).length,120);assert.equal(ach(applied),40);const matrix=RI.parseRosterGrid(RI.csvGrid('Person,18/11/2026,19/11/2026\nDemo A,MX2,MXOFF'),s,people,month,'DMY','matrix.csv');assert.equal(matrix.entries.length,2);assert.equal(matrix.entries[0].code,'MX2');assert.equal(RI.readRosterDate('MX1',month),'');});
check('shift timing, overnight, split breaks and unknown-code review are enforced',()=>{let s=base();s.workSchedules={me:{...AV.emptySchedule(),requireSchedule:true,windows:[{id:'w',start:today,end:today,available:true,code:'MX1'}]}};assert.equal(AV.isAvailableAt(s,'me',today,'06:59'),false);assert.equal(AV.isAvailableAt(s,'me',today,'07:00'),true);assert.equal(AV.isAvailableAt(s,'me',today,'16:00'),false);s.workSchedules.me.windows[0].code='MX18';assert.equal(AV.isAvailableAt(s,'me',today,'23:00'),true);assert.equal(AV.isAvailableAt(s,'me','2026-11-19','06:59'),true);assert.equal(AV.isAvailableAt(s,'me','2026-11-19','07:00'),false);s.shiftCodes=[{code:'CUSTOM',name:'Split',available:true,periods:[{start:'09:00',end:'12:00'},{start:'16:00',end:'20:00'}]}];s.workSchedules.me.windows[0].code='CUSTOM';assert.equal(AV.isAvailableAt(s,'me',today,'10:00'),true);assert.equal(AV.isAvailableAt(s,'me',today,'13:00'),false);assert.equal(AV.isAvailableAt(s,'me',today,'17:00'),true);s.shiftCodes[0].needsReview=true;assert.equal(AV.isAvailableAt(s,'me',today,'17:00'),false);});
