check('assistant plain settings are previewed, applied only explicitly, and undo preserves newer preferences',()=>{const s=pending('Turn off auto-detection'),p=AS.previewAssistant(s,phones,team,today,s.assistantRequests[0].text);assert.equal(p.settings.after['retaillens-processing-v1'].includes('"autoFindBoxes":false'),true);assert.equal(preferences.size,0);const result=AS.applyAssistantRequest(s,phones,team,today,'ask');SET.writeSettingsSnapshot(result.settings);assert.equal(JSON.parse(preferences.get('retaillens-processing-v1')).autoFindBoxes,false);const undone=AS.undoAssistantRequest(result.next,phones,'ask');SET.writeSettingsSnapshot(undone.settings);assert.equal(preferences.has('retaillens-processing-v1'),false);SET.writeSettingsSnapshot(result.settings);preferences.set('retaillens-processing-v1','{}');assert.throws(()=>AS.undoAssistantRequest(result.next,phones,'ask'),/settings changed/);preferences.clear();});
check('assistant assigns4 and10 exact models, emits a receipt, and undoes ownership without sales',()=>{const s=pending('give 4 Fold6 to Maya and 10 to Noor'),snapshot=JSON.stringify(s),preview=AS.previewAssistant(s,phones,team,today,s.assistantRequests[0].text);assert.deepEqual(preview.blockers,[]);assert.equal(preview.giving.reduce((n,p)=>n+p.recordIds.length,0),14);assert.equal(JSON.stringify(s),snapshot);const applied=AS.applyAssistantRequest(s,phones,team,today,'ask'),rows=ownersAfter(phones,applied.changes);assert.equal(rows.filter(r=>r.personId==='maya').length,4);assert.equal(rows.filter(r=>r.personId==='noor').length,10);assert.equal(applied.next.assistantRequests[0].status,'applied');assert.equal(applied.next.releases.length,0);assert.equal(I.realStock(applied.next,rows).length,20);const clean=D.cleanState(applied.next);assert.equal(clean.assistantRequests[0].allocationId,applied.next.allocations[0].id);const undone=AS.undoAssistantRequest(clean,rows,'ask');assert.equal(undone.changes.length,14);assert.ok(ownersAfter(rows,undone.changes).every(r=>!r.personId));assert.equal(undone.next.assistantRequests[0].status,'undone');});
check('assistant blocks ambiguous models, shortage, invalid IMEIs and unavailable giving without reviewed override',()=>{let s=pending('give 4 Fold to Maya');assert.ok(AS.previewAssistant(s,[...phones,{...phones[0],id:'another',model:'SM-F966B'}],team,today,s.assistantRequests[0].text).blockers.length);s=pending('give 21 Fold6 to Maya');assert.throws(()=>AS.applyAssistantRequest(s,phones,team,today,'ask'),/only20|only 20/);s=pending('give 20 Fold6 to Maya');assert.ok(AS.previewAssistant(s,phones.map((r,i)=>i===0?{...r,imei:'000000000000001'}:r),team,today,s.assistantRequests[0].text).blockers.length);s=pending('give 4 Fold6 to Maya');s.workSchedules={maya:{...AV.emptySchedule(),offDates:[today]}};assert.throws(()=>AS.applyAssistantRequest(s,phones,team,today,'ask'),/warnings/);assert.equal(AS.applyAssistantRequest(s,phones,team,today,'ask',true).changes.length,4);});
check('assistant report draft previews mismatch, preserves real stock, and undo refuses newer report edits',()=>{const s=pending('set report Fold6 to 6'),preview=AS.previewAssistant(s,phones,team,today,s.assistantRequests[0].text);assert.equal(preview.report.after.entries.filter(r=>r.t==='item')[0].sold,6);assert.ok(preview.warnings.length);const applied=AS.applyAssistantRequest(s,phones,team,today,'ask',true);assert.equal(I.realStock(applied.next,phones).length,20);assert.equal(ach(applied.next),40);assert.equal(applied.next.reportDrafts[today].mode,'manual');const restored=D.cleanState(applied.next),undo=AS.undoAssistantRequest(restored,phones,'ask');assert.equal(undo.next.reportDrafts[today],undefined);const changed=structuredClone(applied.next);changed.reportDrafts[today].report.entries.find(e=>e.t==='item').sold=9;assert.throws(()=>AS.undoAssistantRequest(changed,phones,'ask'),/report changed/);});
check('assistant stock, target division and date range actions preview then undo through existing domain rules',()=>{let s=pending('store 4 Fold6'),result=AS.applyAssistantRequest(s,phones,team,today,'ask');assert.equal(Object.values(result.next.recordMeta).filter(m=>m.status==='held').length,4);assert.equal(I.realStock(result.next,phones).length,20);assert.deepEqual(AS.undoAssistantRequest(D.cleanState(result.next),phones,'ask').next.recordMeta,{});s=pending('split store target 120 for Flagship 1 among everyone');s.targets={};result=AS.applyAssistantRequest(s,phones,team,today,'ask');assert.deepEqual(team.map(p=>result.next.targets[month][p.id].lines[0].target),[40,40,40]);assert.deepEqual(AS.undoAssistantRequest(D.cleanState(result.next),phones,'ask').next.targets,{});s=pending('mark Maya not available from 2026-11-20 to 2026-11-24');result=AS.applyAssistantRequest(s,phones,team,today,'ask',true);assert.equal(AV.availability(result.next,'maya','2026-11-22'),'annual leave');assert.deepEqual(result.next.targets,s.targets);assert.deepEqual(AS.undoAssistantRequest(D.cleanState(result.next),phones,'ask').next.workSchedules,{});});
check('assistant understands natural wording for a store target and divides it equally between the promoters (preview first, nothing changed)',()=>{
  const ask=text=>AS.previewAssistant({...base(),recordMeta:{},targets:{}},phones,team,today,text);
  const A=(text,fn)=>{try{fn(ask(text));}catch(error){throw new Error(`[${text}] `+error.message);}};
  A('change flagship 3 target to 12 and divide it to promoters',p=>{assert.equal(p.handled,true);assert.deepEqual(p.blockers,[]);assert.match(p.lines[0],/Flagship 3: store target 12; equal base split across 3 people/);assert.equal(p.business.after.targets[month][team[0].id].lines.find(l=>l.segment==='flagship3').target,4,'12 divided between 3 promoters is 4 each');});
  const s=pending('change flagship 3 target to 12 and divide it to promoters');s.targets={};const result=AS.applyAssistantRequest(s,phones,team,today,'ask');
  assert.deepEqual(team.map(person=>result.next.targets[month][person.id].lines.find(l=>l.segment==='flagship3').target),[4,4,4]);
  assert.deepEqual(AS.undoAssistantRequest(D.cleanState(result.next),phones,'ask').next.targets,{},'and Undo takes it back');
  A('set store target for Flagship 2 to 20 and share it among everyone',p=>{assert.deepEqual(p.blockers,[]);assert.match(p.lines[0],/Flagship 2: store target 20/);});
  A('split store target 120 for Flagship 1 among everyone',p=>{assert.deepEqual(p.blockers,[]);assert.match(p.lines[0],/Flagship 1: store target 120/);});
  A('please make the Flagship 1 store target 60 and divide it equally between all promoters',p=>{assert.deepEqual(p.blockers,[]);assert.match(p.lines[0],/Flagship 1: store target 60/);});
  // unclear requests are explained, never guessed
  A('change flagship 3 target to 12',p=>{assert.equal(p.handled,true);assert.match(p.blockers[0],/Is this the store target to divide between the promoters/);assert.equal(p.business,undefined);});
  A('change flagship 3 target to 12 and divide it to Maya',p=>assert.match(p.blockers[0],/Say who shares it/));
  A('divide flagship 9 target to 12 among everyone',p=>assert.match(p.blockers[0],/Choose one saved segment by name/));
  A('divide the store target among everyone',p=>assert.match(p.blockers[0],/Choose one saved segment by name|Say the store target number/));
  // ordinary questions that only mention targets or sharing are left alone
  for(const text of ['how do I share my targets','show my targets','what is my target for flagship 3','share the report with Maya']) A(text,p=>assert.equal(p.handled,false));
});
