check('assistant file reports are data-only reviewed drafts or approved accessory snapshots, with backup and undo',()=>{let s=pending('Imported file');s.assistantRequests[0].fileReport={date:today,text:'Galaxy Z Fold6 256GB: 00/20',category:'phones'};let result=AS.applyAssistantRequest(s,phones,team,today,'ask',true);assert.equal(result.next.reportDrafts[today].mode,'manual');assert.equal(I.realStock(result.next,phones).length,20);assert.equal(D.cleanState(result.next).assistantRequests[0].fileReport.category,'phones');s=pending('Imported accessory file');s.assistantRequests[0].fileReport={date:today,text:'Daily OSR\nBuds4: 00/08\nSamsung Sold: 00',category:'accessories'};result=AS.applyAssistantRequest(s,phones,team,today,'ask');assert.equal(result.next.accessoryStock.buds4.quantity,8);assert.equal(P.reportItems(result.next.accessoryReport)[0].stock,8);const undo=AS.undoAssistantRequest(D.cleanState(result.next),phones,'ask');assert.deepEqual(undo.next.accessoryStock,{});assert.equal(undo.next.accessoryReport,undefined);const report=DR.calculatedDatedReport({...base(),recordMeta:{}},phones,today,today);assert.equal(DR.compareDatedReport({...base(),recordMeta:{}},phones,report,today,today).match,true,'generated Fold abbreviation verifies against its own source');});
